CREATE TABLE channels (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL REFERENCES workspaces(id), telegram_chat_id bigint NOT NULL, title text NOT NULL, status text NOT NULL CHECK(status IN('CONNECTED','DISCONNECTED')), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(workspace_id,telegram_chat_id), UNIQUE(id,workspace_id));
CREATE INDEX channels_workspace ON channels(workspace_id);
CREATE TABLE channel_settings (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL REFERENCES workspaces(id), channel_id uuid NOT NULL, settings jsonb NOT NULL DEFAULT '{}', updated_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(channel_id,workspace_id) REFERENCES channels(id,workspace_id), UNIQUE(channel_id), UNIQUE(id,workspace_id));
CREATE INDEX channel_settings_workspace ON channel_settings(workspace_id);
CREATE TABLE groups (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL REFERENCES workspaces(id), telegram_chat_id bigint NOT NULL, title text NOT NULL, status text NOT NULL CHECK(status IN('CONNECTED','DISCONNECTED')), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(workspace_id,telegram_chat_id), UNIQUE(id,workspace_id));
CREATE INDEX groups_workspace ON groups(workspace_id);
CREATE TABLE group_settings (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL REFERENCES workspaces(id), group_id uuid NOT NULL, moderation jsonb NOT NULL DEFAULT '{}', security jsonb NOT NULL DEFAULT '{}', updated_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(group_id,workspace_id) REFERENCES groups(id,workspace_id), UNIQUE(group_id), UNIQUE(id,workspace_id));
CREATE INDEX group_settings_workspace ON group_settings(workspace_id);
CREATE TABLE customer_bots (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL REFERENCES workspaces(id), name text NOT NULL, username text NOT NULL, key_id text NOT NULL, encrypted_token bytea NOT NULL, status text NOT NULL CHECK(status IN('DRAFT','VERIFIED','RUNNING','DISABLED')), idempotency_key text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(workspace_id,idempotency_key), UNIQUE(username), UNIQUE(id,workspace_id));
CREATE INDEX customer_bots_workspace ON customer_bots(workspace_id);
CREATE TABLE customer_bot_modules (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL REFERENCES workspaces(id), bot_id uuid NOT NULL, plugin_key text NOT NULL REFERENCES plugins(key), enabled boolean NOT NULL DEFAULT false, configuration jsonb NOT NULL DEFAULT '{}', FOREIGN KEY(bot_id,workspace_id) REFERENCES customer_bots(id,workspace_id), UNIQUE(bot_id,plugin_key), UNIQUE(id,workspace_id));
CREATE INDEX customer_bot_modules_workspace ON customer_bot_modules(workspace_id);
CREATE TABLE customer_bot_settings (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL REFERENCES workspaces(id), bot_id uuid NOT NULL, locale text NOT NULL DEFAULT 'fa-IR', settings jsonb NOT NULL DEFAULT '{}', FOREIGN KEY(bot_id,workspace_id) REFERENCES customer_bots(id,workspace_id), UNIQUE(bot_id), UNIQUE(id,workspace_id));
CREATE INDEX customer_bot_settings_workspace ON customer_bot_settings(workspace_id);
CREATE TABLE access_gates (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL REFERENCES workspaces(id), name text NOT NULL, enabled boolean NOT NULL DEFAULT false, mode text NOT NULL CHECK(mode IN('ALL_REQUIRED','ANY_REQUIRED','MINIMUM_REQUIRED')), minimum_required integer NOT NULL DEFAULT 1 CHECK(minimum_required>0), message_key text NOT NULL DEFAULT 'gate.required', created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(id,workspace_id));
CREATE INDEX access_gates_workspace ON access_gates(workspace_id);
CREATE TABLE access_gate_channels (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL REFERENCES workspaces(id), gate_id uuid NOT NULL, telegram_chat_id bigint NOT NULL, join_url text NOT NULL, position integer NOT NULL DEFAULT 0, FOREIGN KEY(gate_id,workspace_id) REFERENCES access_gates(id,workspace_id), UNIQUE(gate_id,telegram_chat_id), UNIQUE(id,workspace_id));
CREATE INDEX access_gate_channels_workspace ON access_gate_channels(workspace_id);
CREATE TABLE access_gate_verifications (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL REFERENCES workspaces(id), gate_id uuid NOT NULL, user_id uuid NOT NULL REFERENCES users(id), passed boolean NOT NULL, expires_at timestamptz NOT NULL, checked_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(gate_id,workspace_id) REFERENCES access_gates(id,workspace_id), UNIQUE(gate_id,user_id), UNIQUE(id,workspace_id));
CREATE INDEX access_gate_verifications_workspace ON access_gate_verifications(workspace_id);
CREATE TABLE broadcasts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL REFERENCES workspaces(id), actor_id uuid NOT NULL REFERENCES users(id), name text NOT NULL, mode text NOT NULL CHECK(mode IN('SEND','COPY','FORWARD')), content jsonb NOT NULL, audience_filter jsonb NOT NULL, status text NOT NULL CHECK(status IN('DRAFT','SCHEDULED','QUEUED','RUNNING','PAUSED','COMPLETED','CANCELLED','FAILED')), scheduled_at timestamptz, idempotency_key text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(workspace_id,idempotency_key), UNIQUE(id,workspace_id));
CREATE INDEX broadcasts_workspace ON broadcasts(workspace_id);
CREATE TABLE broadcast_audiences (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL REFERENCES workspaces(id), broadcast_id uuid NOT NULL, filter jsonb NOT NULL, snapshot_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(broadcast_id,workspace_id) REFERENCES broadcasts(id,workspace_id), UNIQUE(id,workspace_id));
CREATE INDEX broadcast_audiences_workspace ON broadcast_audiences(workspace_id);
CREATE TABLE broadcast_recipients (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL REFERENCES workspaces(id), broadcast_id uuid NOT NULL, user_id uuid NOT NULL REFERENCES users(id), status text NOT NULL CHECK(status IN('PENDING','SENDING','DELIVERED','RETRYABLE','PERMANENT_FAILURE','UNKNOWN','SKIPPED')), attempts integer NOT NULL DEFAULT 0, lease_until timestamptz, FOREIGN KEY(broadcast_id,workspace_id) REFERENCES broadcasts(id,workspace_id), UNIQUE(broadcast_id,user_id), UNIQUE(id,workspace_id));
CREATE INDEX broadcast_recipients_workspace ON broadcast_recipients(workspace_id);
CREATE TABLE broadcast_deliveries (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL REFERENCES workspaces(id), recipient_id uuid NOT NULL, telegram_message_id bigint, error_code text, status text NOT NULL CHECK(status IN('DELIVERED','RETRYABLE','PERMANENT_FAILURE','UNKNOWN')), created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(recipient_id,workspace_id) REFERENCES broadcast_recipients(id,workspace_id), UNIQUE(id,workspace_id));
CREATE INDEX broadcast_deliveries_workspace ON broadcast_deliveries(workspace_id);
CREATE TABLE tickets (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL REFERENCES workspaces(id), creator_id uuid NOT NULL REFERENCES users(id), subject text NOT NULL CHECK(length(subject) BETWEEN 1 AND 200), status text NOT NULL DEFAULT 'OPEN' CHECK(status IN('OPEN','PENDING','WAITING_FOR_CUSTOMER','WAITING_FOR_AGENT','IN_PROGRESS','RESOLVED','CLOSED')), priority text NOT NULL DEFAULT 'NORMAL' CHECK(priority IN('LOW','NORMAL','HIGH','URGENT')), assignee_id uuid REFERENCES users(id), category text NOT NULL DEFAULT 'general', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(id,workspace_id));
CREATE INDEX tickets_workspace ON tickets(workspace_id);
CREATE TABLE ticket_messages (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL REFERENCES workspaces(id), ticket_id uuid NOT NULL, actor_id uuid NOT NULL REFERENCES users(id), body text NOT NULL CHECK(length(body) BETWEEN 1 AND 4000), idempotency_key text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(ticket_id,workspace_id) REFERENCES tickets(id,workspace_id), UNIQUE(workspace_id,idempotency_key), UNIQUE(id,workspace_id));
CREATE INDEX ticket_messages_workspace ON ticket_messages(workspace_id);
CREATE TABLE ticket_participants (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL REFERENCES workspaces(id), ticket_id uuid NOT NULL, user_id uuid NOT NULL REFERENCES users(id), FOREIGN KEY(ticket_id,workspace_id) REFERENCES tickets(id,workspace_id), UNIQUE(ticket_id,user_id), UNIQUE(id,workspace_id));
CREATE INDEX ticket_participants_workspace ON ticket_participants(workspace_id);
CREATE TABLE ticket_assignments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL REFERENCES workspaces(id), ticket_id uuid NOT NULL, actor_id uuid NOT NULL REFERENCES users(id), assignee_id uuid NOT NULL REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(ticket_id,workspace_id) REFERENCES tickets(id,workspace_id), UNIQUE(id,workspace_id));
CREATE INDEX ticket_assignments_workspace ON ticket_assignments(workspace_id);
CREATE TABLE ticket_tags (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL REFERENCES workspaces(id), ticket_id uuid NOT NULL, tag text NOT NULL, FOREIGN KEY(ticket_id,workspace_id) REFERENCES tickets(id,workspace_id), UNIQUE(ticket_id,tag), UNIQUE(id,workspace_id));
CREATE INDEX ticket_tags_workspace ON ticket_tags(workspace_id);
CREATE TABLE ticket_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL REFERENCES workspaces(id), ticket_id uuid NOT NULL, actor_id uuid NOT NULL REFERENCES users(id), event_type text NOT NULL, detail jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(ticket_id,workspace_id) REFERENCES tickets(id,workspace_id), UNIQUE(id,workspace_id));
CREATE INDEX ticket_events_workspace ON ticket_events(workspace_id);
CREATE TABLE ticket_sla_records (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL REFERENCES workspaces(id), ticket_id uuid NOT NULL, response_due_at timestamptz NOT NULL, resolution_due_at timestamptz NOT NULL, first_response_at timestamptz, resolved_at timestamptz, FOREIGN KEY(ticket_id,workspace_id) REFERENCES tickets(id,workspace_id), UNIQUE(id,workspace_id));
CREATE INDEX ticket_sla_records_workspace ON ticket_sla_records(workspace_id);
CREATE TABLE ticket_internal_notes (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL REFERENCES workspaces(id), ticket_id uuid NOT NULL, actor_id uuid NOT NULL REFERENCES users(id), body text NOT NULL CHECK(length(body) BETWEEN 1 AND 4000), created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(ticket_id,workspace_id) REFERENCES tickets(id,workspace_id), UNIQUE(id,workspace_id));
CREATE INDEX ticket_internal_notes_workspace ON ticket_internal_notes(workspace_id);
CREATE TABLE download_jobs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL REFERENCES workspaces(id), creator_id uuid NOT NULL REFERENCES users(id), provider text NOT NULL CHECK(provider IN('youtube','instagram','facebook')), source_url text NOT NULL, format_id text NOT NULL, formats jsonb NOT NULL, state text NOT NULL CHECK(state IN('QUEUED','ANALYZING','AWAITING_FORMAT','DOWNLOADING','PROCESSING','UPLOADING','COMPLETED','FAILED','CANCELLED')), synthetic boolean NOT NULL, idempotency_key text NOT NULL, error_code text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(workspace_id,idempotency_key), UNIQUE(id,workspace_id));
CREATE INDEX download_jobs_workspace ON download_jobs(workspace_id);
CREATE TABLE download_assets (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL REFERENCES workspaces(id), download_job_id uuid NOT NULL, storage_key text NOT NULL, size_bytes bigint NOT NULL CHECK(size_bytes>=0), created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(download_job_id,workspace_id) REFERENCES download_jobs(id,workspace_id), UNIQUE(id,workspace_id));
CREATE INDEX download_assets_workspace ON download_assets(workspace_id);
CREATE TABLE uploads (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL REFERENCES workspaces(id), creator_id uuid NOT NULL REFERENCES users(id), customer_bot_id uuid, state text NOT NULL CHECK(state IN('RECEIVED','VALIDATING','PENDING_APPROVAL','PROCESSING','STORED','REJECTED','FAILED')), metadata jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(customer_bot_id,workspace_id) REFERENCES customer_bots(id,workspace_id), UNIQUE(id,workspace_id));
CREATE INDEX uploads_workspace ON uploads(workspace_id);
CREATE TABLE upload_files (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL REFERENCES workspaces(id), upload_id uuid NOT NULL, storage_key text NOT NULL, media_type text NOT NULL, size_bytes bigint NOT NULL CHECK(size_bytes>0), FOREIGN KEY(upload_id,workspace_id) REFERENCES uploads(id,workspace_id), UNIQUE(id,workspace_id));
CREATE INDEX upload_files_workspace ON upload_files(workspace_id);
CREATE TABLE upload_workflows (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL REFERENCES workspaces(id), name text NOT NULL, approval_required boolean NOT NULL DEFAULT true, allowed_types jsonb NOT NULL, max_bytes bigint NOT NULL CHECK(max_bytes>0), retention_days integer NOT NULL CHECK(retention_days>0), destination text NOT NULL CHECK(destination IN('TELEGRAM','OBJECT_STORAGE')), UNIQUE(id,workspace_id));
CREATE INDEX upload_workflows_workspace ON upload_workflows(workspace_id);
CREATE TABLE media_assets (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL REFERENCES workspaces(id), storage_key text NOT NULL, content_type text NOT NULL, size_bytes bigint NOT NULL CHECK(size_bytes>=0), sha256 text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(workspace_id,storage_key), UNIQUE(id,workspace_id));
CREATE INDEX media_assets_workspace ON media_assets(workspace_id);
CREATE TABLE media_jobs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL REFERENCES workspaces(id), asset_id uuid, operation text NOT NULL, state text NOT NULL CHECK(state IN('QUEUED','RUNNING','COMPLETED','FAILED','CANCELLED')), idempotency_key text NOT NULL, error_code text, created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(asset_id,workspace_id) REFERENCES media_assets(id,workspace_id), UNIQUE(workspace_id,idempotency_key), UNIQUE(id,workspace_id));
CREATE INDEX media_jobs_workspace ON media_jobs(workspace_id);
CREATE TABLE notifications (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL REFERENCES workspaces(id), user_id uuid NOT NULL REFERENCES users(id), message_key text NOT NULL, parameters jsonb NOT NULL DEFAULT '{}', status text NOT NULL CHECK(status IN('PENDING','DELIVERED','SIMULATED','FAILED','UNKNOWN')), idempotency_key text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(workspace_id,idempotency_key), UNIQUE(id,workspace_id));
CREATE INDEX notifications_workspace ON notifications(workspace_id);
CREATE TABLE analytics_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL REFERENCES workspaces(id), event_type text NOT NULL, user_id uuid REFERENCES users(id), dimensions jsonb NOT NULL DEFAULT '{}', occurred_at timestamptz NOT NULL DEFAULT now(), UNIQUE(id,workspace_id));
CREATE INDEX analytics_events_workspace ON analytics_events(workspace_id);
CREATE TABLE analytics_aggregates (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL REFERENCES workspaces(id), metric text NOT NULL, bucket_start timestamptz NOT NULL, dimensions jsonb NOT NULL DEFAULT '{}', value bigint NOT NULL DEFAULT 0, UNIQUE(workspace_id,metric,bucket_start,dimensions), UNIQUE(id,workspace_id));
CREATE INDEX analytics_aggregates_workspace ON analytics_aggregates(workspace_id);
CREATE TABLE ai_usage (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL REFERENCES workspaces(id), user_id uuid NOT NULL REFERENCES users(id), provider text NOT NULL, capability text NOT NULL, input_tokens bigint NOT NULL CHECK(input_tokens>=0), output_tokens bigint NOT NULL CHECK(output_tokens>=0), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(id,workspace_id));
CREATE INDEX ai_usage_workspace ON ai_usage(workspace_id);
